/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `log_stock_movement_on_batch_update` AFTER UPDATE ON `medicine_batches` FOR EACH ROW BEGIN
    IF OLD.current_stock != NEW.current_stock THEN
        INSERT INTO medicine_stock_movements (
            medicine_id, 
            batch_id, 
            movement_type, 
            quantity, 
            unit_cost, 
            movement_date, 
            notes, 
            hospital_id
        ) VALUES (
            NEW.medicine_id,
            NEW.id,
            'adjustment',
            NEW.current_stock - OLD.current_stock,
            NEW.unit_cost,
            NOW(),
            CONCAT('Stock adjusted from ', OLD.current_stock, ' to ', NEW.current_stock),
            NEW.hospital_id
        );
    END IF;
END */;;
DELIMITER ;
