DROP TABLE IF EXISTS `usage_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `usage_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `inventory_item_id` int(11) NOT NULL,
  `department_id` int(11) DEFAULT NULL,
  `used_by_type` enum('doctor','nurse','patient','department','other') NOT NULL,
  `used_by_id` int(11) DEFAULT NULL,
  `patient_id` int(11) DEFAULT NULL,
  `doctor_id` int(11) DEFAULT NULL,
  `quantity_used` int(11) NOT NULL,
  `unit_cost` decimal(10,2) DEFAULT 0.00,
  `total_cost` decimal(15,2) DEFAULT 0.00,
  `usage_date` timestamp NOT NULL DEFAULT current_timestamp(),
  `purpose` varchar(255) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `batch_number` varchar(100) DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `hospital_id` int(11) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_inventory_item_id` (`inventory_item_id`),
  KEY `idx_hospital_id` (`hospital_id`),
  KEY `idx_usage_date` (`usage_date`),
  KEY `idx_used_by` (`used_by_type`,`used_by_id`),
  KEY `idx_patient_id` (`patient_id`),
  KEY `idx_doctor_id` (`doctor_id`),
  KEY `idx_department_id` (`department_id`),
  KEY `idx_usage_logs_date_hospital` (`usage_date`,`hospital_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1007 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

